changeSet.sql:
DELETE FROM outbox_messages
WHERE aggregate_type = 'TASK'
  AND aggregate_id IN (
    SELECT id FROM tasks
    WHERE type IN ('HTTP_CHECK', 'PORT_CHECK', 'DNS_CHECK', 'PING', 'TLS_CHECK')
  );
DELETE FROM tasks
WHERE type IN ('HTTP_CHECK', 'PORT_CHECK', 'DNS_CHECK', 'PING', 'TLS_CHECK');
ALTER TABLE tasks DROP CONSTRAINT tasks_type_check;
ALTER TABLE tasks ADD CONSTRAINT tasks_type_check CHECK (type IN ('TEST_OPERATION'));

rollback.sql:
